.v1 { position: relative; max-width: 100%; color: var(--text); font-family: -apple-system, 'Segoe UI', Roboto, sans-serif; font-size: 14px; line-height: 1.35; -webkit-text-size-adjust: 100%; }
.v1 * { box-sizing: border-box; min-width: 0; }
.v1 .v1-f { position: absolute; width: 0; height: 0; opacity: 0; pointer-events: none; }
.v1 .v1-head { padding: 2px 0 12px; }
.v1 .v1-title { margin: 0; font-size: 19px; font-weight: 700; letter-spacing: -0.01em; line-height: 1.2; }
.v1 .v1-count { margin: 4px 0 0; font-size: 12.5px; color: var(--muted); font-variant-numeric: tabular-nums; }
.v1 .v1-strip { display: flex; gap: 3px; padding: 3px; background: var(--surface); border: 1px solid var(--border); border-radius: 10px; }
.v1 .v1-tab { flex: 1 1 0; min-width: 0; overflow: hidden; display: flex; align-items: center; justify-content: center; gap: 4px; padding: 7px 2px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--muted); cursor: pointer; user-select: none; white-space: nowrap; transition: background .12s, color .12s; }
.v1 .v1-tab b { font-weight: 700; font-variant-numeric: tabular-nums; color: var(--text); }
.v1 .v1-tab:hover { color: var(--text); background: var(--surface2); }
.v1 .v1-f-all:checked ~ .v1-strip .v1-t-all, .v1 .v1-f-dal:checked ~ .v1-strip .v1-t-dal, .v1 .v1-f-chi:checked ~ .v1-strip .v1-t-chi, .v1 .v1-f-over:checked ~ .v1-strip .v1-t-over, .v1 .v1-f-under:checked ~ .v1-strip .v1-t-under { background: var(--surface2); color: var(--text); box-shadow: inset 0 0 0 1px var(--border), 0 1px 0 rgba(59,130,246,.55); }
.v1 .v1-f:focus-visible ~ .v1-strip { outline: 2px solid var(--accent); outline-offset: 2px; }
.v1 .v1-slots { display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px 8px; padding: 8px 2px 4px; }
.v1 .v1-slot { display: flex; justify-content: space-between; align-items: baseline; gap: 6px; font-size: 11.5px; color: var(--muted); border-bottom: 1px solid var(--border); padding: 3px 0; font-variant-numeric: tabular-nums; }
.v1 .v1-slot span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.v1 .v1-slot b { font-weight: 600; color: var(--text); }
.v1 .v1-list { list-style: none; margin: 10px 0 0; padding: 0; background: var(--surface); border: 1px solid var(--border); border-radius: 12px; overflow: hidden; }
.v1 .v1-row { box-shadow: 0 -1px 0 var(--border); }
.v1 .v1-link { display: flex; align-items: center; gap: 8px; padding: 10px 8px 10px 12px; color: inherit; text-decoration: none; -webkit-tap-highlight-color: rgba(59,130,246,.12); transition: background .12s; }
.v1 .v1-link:hover { background: var(--surface2); }
.v1 .v1-link:active { background: rgba(59,130,246,.10); }
.v1 .v1-link:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.v1 .v1-disc { flex: 0 0 32px; width: 32px; height: 32px; border-radius: 50%; background: var(--surface2); box-shadow: 0 0 0 1px var(--border); display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 700; letter-spacing: .02em; color: var(--text); }
.v1 .v1-main { flex: 1 1 auto; display: flex; flex-direction: column; gap: 2px; }
.v1 .v1-ident { display: flex; flex-wrap: wrap; align-items: center; gap: 2px 6px; }
.v1 .v1-name { flex: 0 1 auto; max-width: 100%; font-weight: 600; font-size: 14px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.v1 .v1-src { flex: 0 0 auto; font-size: 10px; font-weight: 600; letter-spacing: .02em; color: var(--muted); border: 1px solid var(--border); border-radius: 4px; padding: 1px 5px; white-space: nowrap; }
.v1 .v1-met { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0 7px; font-size: 12.5px; font-variant-numeric: tabular-nums; color: var(--muted); }
.v1 .v1-rec { color: var(--text); font-weight: 600; }
.v1 .v1-money { font-weight: 700; }
.v1 .v1-pos { color: var(--green); }
.v1 .v1-neg { color: var(--red); }
.v1 .v1-roi.v1-pos, .v1 .v1-roi.v1-neg { font-weight: 500; opacity: .9; }
.v1 .v1-sub { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px; font-size: 11px; color: var(--muted); }
.v1 .v1-when { white-space: nowrap; font-variant-numeric: tabular-nums; }
.v1 .v1-chip { display: inline-flex; align-items: center; gap: 3px; font-size: 10px; font-weight: 600; line-height: 1; padding: 3px 6px; border-radius: 999px; border: 1px solid var(--border); background: var(--surface2); color: var(--muted); white-space: nowrap; font-variant-numeric: tabular-nums; }
.v1 .v1-chip.v1-w { color: var(--green); border-color: rgba(34,197,94,.35); background: rgba(34,197,94,.10); }
.v1 .v1-chip.v1-l { color: var(--text); border-color: rgba(59,130,246,.30); background: rgba(59,130,246,.10); }
.v1 .v1-pick { flex: 0 0 auto; max-width: 96px; display: flex; flex-direction: column; align-items: flex-end; gap: 3px; text-align: right; }
.v1 .v1-pchip { display: inline-block; max-width: 100%; padding: 5px 8px; border-radius: 7px; background: var(--surface2); border: 1px solid var(--border); font-size: 12.5px; font-weight: 700; font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--text); }
.v1 .v1-price { max-width: 100%; font-size: 10.5px; line-height: 1.25; color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.v1 .v1-chev { flex: 0 0 7px; width: 7px; height: 7px; margin-left: 1px; border-right: 1.5px solid var(--muted); border-bottom: 1.5px solid var(--muted); transform: rotate(-45deg); opacity: .7; }
.v1 .v1-link:hover .v1-chev { border-color: var(--text); opacity: 1; }
.v1 .v1-f-dal:checked ~ .v1-list .v1-row:not(.v1-s-dal), .v1 .v1-f-chi:checked ~ .v1-list .v1-row:not(.v1-s-chi), .v1 .v1-f-over:checked ~ .v1-list .v1-row:not(.v1-s-over), .v1 .v1-f-under:checked ~ .v1-list .v1-row:not(.v1-s-under) { display: none; }
.v1 .v1-empty { display: none; margin: 10px 0 0; padding: 14px 12px; text-align: center; font-size: 12.5px; color: var(--muted); background: var(--surface); border: 1px dashed var(--border); border-radius: 12px; }
.v1 .v1-f-dal:checked ~ .v1-list:not(:has(.v1-s-dal)), .v1 .v1-f-chi:checked ~ .v1-list:not(:has(.v1-s-chi)), .v1 .v1-f-over:checked ~ .v1-list:not(:has(.v1-s-over)), .v1 .v1-f-under:checked ~ .v1-list:not(:has(.v1-s-under)) { display: none; }
.v1 .v1-f-dal:checked ~ .v1-list:not(:has(.v1-s-dal)) ~ .v1-empty, .v1 .v1-f-chi:checked ~ .v1-list:not(:has(.v1-s-chi)) ~ .v1-empty, .v1 .v1-f-over:checked ~ .v1-list:not(:has(.v1-s-over)) ~ .v1-empty, .v1 .v1-f-under:checked ~ .v1-list:not(:has(.v1-s-under)) ~ .v1-empty { display: block; }
.v1 .v1-note { margin: 12px 0 0; font-size: 12.5px; color: var(--muted); }
.v1 .v1-unq { margin: 6px 0 0; font-size: 12.5px; color: var(--muted); font-variant-numeric: tabular-nums; }
.v1 .v1-grade { margin: 14px 0 0; padding-top: 10px; border-top: 1px solid var(--border); font-size: 11px; line-height: 1.45; color: var(--muted); }
@media (min-width: 560px) { .v1 .v1-pick { max-width: 150px; } .v1 .v1-price { white-space: normal; } .v1 .v1-price br { display: none; } .v1 .v1-slots { grid-template-columns: repeat(6, 1fr); } }

.v2 .v2-wrap{font-family:-apple-system,'Segoe UI',Roboto,sans-serif;color:var(--text);font-variant-numeric:tabular-nums;max-width:100%;box-sizing:border-box;line-height:1.3}
.v2 .v2-wrap *{box-sizing:border-box;min-width:0}
.v2 .v2-head{display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:2px 12px;margin:0 0 10px}
.v2 .v2-title{font-size:18px;font-weight:700;letter-spacing:-.01em;margin:0}
.v2 .v2-count{font-size:12px;color:var(--muted);margin:0}
.v2 .v2-card{background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:0 12px 6px;overflow:hidden}
.v2 .v2-match{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;column-gap:8px;padding:12px 0 10px;border-bottom:1px solid var(--border)}
.v2 .v2-tm{display:flex;flex-direction:column;gap:2px}
.v2 .v2-tmn{font-size:14px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v2 .v2-tmrec{font-size:11px;color:var(--muted);letter-spacing:.02em}
.v2 .v2-tm-h{align-items:flex-end;text-align:right}
.v2 .v2-at{font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);border:1px solid var(--border);border-radius:999px;padding:2px 7px}
.v2 .v2-when{grid-column:1/-1;text-align:center;font-size:11px;color:var(--muted);margin-top:5px}
.v2 .v2-sides{display:grid;grid-template-columns:1fr 1fr;column-gap:12px;position:relative}
.v2 .v2-sides::before{content:"";position:absolute;left:50%;top:10px;bottom:6px;width:1px;background:var(--border)}
.v2 .v2-col{display:flex;flex-direction:column}
.v2 .v2-colhead{padding:12px 0 6px}
.v2 .v2-team{display:flex;align-items:baseline;flex-wrap:wrap;gap:4px 6px}
.v2 .v2-abbr{font-size:22px;font-weight:800;letter-spacing:-.02em;line-height:1}
.v2 .v2-abbr-s{font-size:17px}
.v2 .v2-px{font-size:11px;color:var(--muted)}
.v2 .v2-n,.v2 .v2-tn{margin-left:auto;font-size:11px;font-weight:600;background:var(--surface2);border:1px solid var(--border);border-radius:999px;padding:2px 8px;white-space:nowrap;line-height:1.3}
.v2 .v2-slots{display:flex;flex-direction:column;gap:2px;margin-top:8px}
.v2 .v2-slot{font-size:11px;color:var(--muted)}
.v2 .v2-slot b{color:var(--text);font-weight:700;display:inline-block;min-width:11px}
.v2 .v2-slot.v2-zero b{color:var(--muted)}
.v2 .v2-empty{padding:16px 0;font-size:12px;color:var(--muted);text-align:center;border-top:1px solid var(--border)}
.v2 .v2-row{display:flex;align-items:flex-start;gap:8px;padding:10px 14px 10px 0;border-top:1px solid var(--border);text-decoration:none;color:inherit;position:relative;-webkit-tap-highlight-color:rgba(59,130,246,.15)}
.v2 .v2-row::after{content:"";position:absolute;top:50%;right:2px;width:7px;height:7px;border-right:1.5px solid var(--muted);border-bottom:1.5px solid var(--muted);transform:translateY(-50%) rotate(-45deg);opacity:.75}
.v2 .v2-row:hover .v2-name,.v2 .v2-row:active .v2-name{color:var(--accent)}
.v2 .v2-row:hover::after,.v2 .v2-row:active::after{border-color:var(--accent);opacity:1}
.v2 .v2-row:focus-visible{outline:2px solid var(--accent);outline-offset:-2px;border-radius:8px}
.v2 .v2-av{flex:0 0 28px;width:28px;height:28px;border-radius:50%;background:var(--surface2);border:1px solid var(--border);color:var(--muted);font-size:11px;font-weight:700;letter-spacing:.03em;display:flex;align-items:center;justify-content:center;margin-top:1px}
.v2 .v2-body{flex:1 1 auto;display:flex;flex-direction:column;gap:3px}
.v2 .v2-l1{display:flex;align-items:center}
.v2 .v2-name{font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v2 .v2-mk{font-size:9px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);border:1px solid var(--border);border-radius:4px;padding:1px 4px;line-height:1.2}
.v2 .v2-pick{display:flex;flex-wrap:wrap;align-items:center;gap:3px 6px;font-size:13px;font-weight:600}
.v2 .v2-price{display:inline-block;font-size:10px;font-weight:600;color:var(--muted);background:var(--surface2);border-radius:4px;padding:2px 5px;line-height:1.25;white-space:nowrap}
.v2 .v2-pl{flex:0 0 100%;display:flex}
.v2 .v2-stat{display:flex;flex-wrap:wrap;gap:2px 6px;font-size:11.5px;color:var(--muted)}
.v2 .v2-stat b{font-weight:600;color:var(--text)}
.v2 .v2-pos{color:var(--green)}
.v2 .v2-neg{color:var(--red)}
.v2 .v2-meta{display:flex;flex-wrap:wrap;align-items:center;gap:3px 6px;font-size:10.5px;color:var(--muted)}
.v2 .v2-src{font-size:9px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;border:1px solid var(--border);border-radius:4px;padding:1px 4px;line-height:1.2}
.v2 .v2-chip{font-size:9.5px;font-weight:600;color:var(--accent);background:rgba(59,130,246,.12);border-radius:4px;padding:1px 5px;line-height:1.3;white-space:nowrap}
.v2 .v2-chip.v2-up{color:var(--gold);background:rgba(255,215,0,.12)}
.v2 .v2-chip.v2-dn{color:var(--accent);background:rgba(59,130,246,.12)}
.v2 .v2-mir{text-align:right}
.v2 .v2-mir .v2-team,.v2 .v2-mir .v2-row{flex-direction:row-reverse}
.v2 .v2-mir .v2-l1,.v2 .v2-mir .v2-pick,.v2 .v2-mir .v2-stat,.v2 .v2-mir .v2-meta,.v2 .v2-mir .v2-pl{justify-content:flex-end}
.v2 .v2-mir .v2-n{margin-left:0;margin-right:auto}
.v2 .v2-mir .v2-slots{align-items:flex-end}
.v2 .v2-mir .v2-row{padding:10px 0 10px 16px}
.v2 .v2-mir .v2-row::after{right:auto;left:4px;transform:translateY(-50%) rotate(135deg)}
.v2 .v2-tband{display:flex;align-items:baseline;gap:8px;padding:14px 0 0;margin-top:8px;border-top:1px solid var(--border)}
.v2 .v2-tlabel{font-size:10px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
.v2 .v2-tline{font-size:17px;font-weight:800;line-height:1}
.v2 .v2-foot{padding:14px 2px 0;display:flex;flex-direction:column;gap:6px}
.v2 .v2-hum,.v2 .v2-unq{font-size:12px;color:var(--muted);margin:0;line-height:1.45}
.v2 .v2-note{font-size:10.5px;color:var(--muted);opacity:.8;margin:6px 0 0;line-height:1.45}

.v3 {font-family:-apple-system,'Segoe UI',Roboto,sans-serif;color:var(--text);background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:16px 14px 14px;max-width:100%;box-sizing:border-box;font-variant-numeric:tabular-nums;line-height:1.35}
