.v3 .v3-side{background:var(--bg);border:1px solid var(--border);border-radius:12px;overflow:hidden}
.v3 .v3-side-head{display:flex;flex-wrap:wrap;align-items:baseline;gap:2px 8px;padding:10px 12px;background:var(--surface2);border-bottom:1px solid var(--border)}
.v3 .v3-side-team{flex:1;font-size:14px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
