.v3 .v3-side-line{font-size:14px;font-weight:700;white-space:nowrap}
.v3 .v3-side-n{flex-basis:100%;font-size:11px;color:var(--muted)}
.v3 .v3-list{list-style:none;margin:0;padding:0}
.v3 .v3-list li+li{border-top:1px solid var(--border)}
.v3 .v3-empty{margin:0;padding:16px 12px;font-size:12.5px;color:var(--muted);text-align:center}
.v3 .v3-row{display:flex;align-items:flex-start;gap:10px;padding:11px 10px 11px 12px;color:inherit;text-decoration:none;-webkit-tap-highlight-color:rgba(59,130,246,.15)}
.v3 .v3-row:hover,.v3 .v3-row:focus-visible{background:rgba(59,130,246,.07);outline:none}
.v3 .v3-row:active{background:rgba(59,130,246,.12)}
.v3 .v3-av{flex:0 0 34px;width:34px;height:34px;border-radius:50%;background:var(--surface2);box-shadow:0 0 0 1px var(--border);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;letter-spacing:.04em;color:var(--text)}
.v3 .v3-body{flex:1;display:flex;flex-direction:column;gap:4px}
.v3 .v3-l1{display:flex;align-items:center;gap:8px}
.v3 .v3-name{font-size:14px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v3 .v3-src{flex:none;font-size:9.5px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);border:1px solid var(--border);border-radius:4px;padding:2px 5px;line-height:1;white-space:nowrap}
.v3 .v3-l2{display:flex;flex-wrap:wrap;gap:2px 10px;font-size:12.5px;color:var(--muted)}
.v3 .v3-l2 b{color:var(--text);font-weight:600}
.v3 .pos{color:var(--green);font-weight:700}
.v3 .neg{color:var(--red);font-weight:700}
.v3 .v3-l3{display:flex;flex-wrap:wrap;align-items:center;gap:5px 6px;font-size:12.5px}
.v3 .v3-pick{font-weight:700;color:var(--text)}
.v3 .v3-chip{font-size:11px;line-height:1;padding:4px 7px;border-radius:999px;background:var(--surface2);border:1px solid var(--border);color:var(--muted);white-space:nowrap}
.v3 .v3-chip.w{color:var(--gold);border-color:rgba(255,215,0,.35);background:rgba(255,215,0,.08)}
.v3 .v3-chip.l{color:var(--accent);border-color:rgba(59,130,246,.35);background:rgba(59,130,246,.1)}
.v3 .v3-when{font-size:11.5px;color:var(--muted)}
.v3 .v3-chev{flex:none;align-self:center;width:8px;height:8px;margin-right:2px;border-right:1.5px solid var(--muted);border-bottom:1.5px solid var(--muted);transform:rotate(-45deg);opacity:.75;transition:transform .15s}
.v3 .v3-panel{margin:0 0 8px}
.v3 .v3-fold{display:flex;align-items:center;gap:10px;padding:10px 12px;background:var(--bg);border:1px solid var(--border);border-radius:12px;cursor:pointer;list-style:none;-webkit-tap-highlight-color:rgba(59,130,246,.15)}
