.v7 .v7-cap .v7-chev{margin-top:-3px}
.v7 .v7-id{display:flex;align-items:center;gap:8px}
.v7 .v7-disc{flex:0 0 auto;width:24px;height:24px;border-radius:50%;background:var(--surface2);border:1px solid var(--border);display:inline-flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:var(--text);letter-spacing:.02em}
.v7 .v7-disc-lg{width:40px;height:40px;font-size:14px;box-shadow:0 0 0 2px var(--bg),0 0 0 3px var(--border)}
.v7 .v7-who{flex:1 1 auto;display:flex;flex-direction:column;gap:3px}
.v7 .v7-name{font-size:13.5px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.v7 .v7-src{display:inline-block;align-self:flex-start;font-size:10px;line-height:1;padding:3px 6px;border-radius:4px;background:rgba(59,130,246,.14);color:var(--accent);white-space:nowrap}
.v7 .v7-chev{flex:0 0 auto;color:var(--muted);font-size:18px;line-height:1}
.v7 .v7-stats{display:flex;flex-wrap:wrap;gap:6px 12px;margin:10px 0 8px;padding:8px 0;border-top:1px solid var(--border);border-bottom:1px solid var(--border)}
.v7 .v7-stats span{flex:0 0 auto;display:flex;flex-direction:column;gap:2px}
.v7 .v7-stats i{font-style:normal;font-size:9px;letter-spacing:.04em;text-transform:uppercase;color:var(--muted);white-space:nowrap}
.v7 .v7-stats b{font-size:13px;font-weight:700}
.v7 .v7-pos{color:var(--green)}
.v7 .v7-neg{color:var(--red)}
.v7 .v7-pick{display:flex;flex-wrap:wrap;align-items:center;gap:4px 6px}
.v7 .v7-pick b{font-size:15px;font-weight:700}
.v7 .v7-price{font-size:10px;line-height:1.3;padding:2px 6px;border-radius:999px;border:1px solid var(--border);background:var(--surface2);color:var(--muted)}
.v7 .v7-when{display:block;margin-top:5px;font-size:11px;color:var(--muted)}
.v7 .v7-chips{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px}
.v7 .v7-chip{font-size:10px;padding:2px 6px;border-radius:4px;background:var(--surface2);border:1px solid var(--border);color:var(--muted)}
.v7 .v7-streak-w{background:rgba(255,215,0,.12);border-color:rgba(255,215,0,.35);color:var(--gold)}
.v7 .v7-streak-l{background:rgba(59,130,246,.12);border-color:rgba(59,130,246,.35);color:var(--accent)}
.v7 .v7-more{margin-top:6px}
.v7 .v7-more summary{list-style:none;cursor:pointer;font-size:12px;color:var(--accent);padding:6px 4px;display:flex;align-items:center;gap:8px;user-select:none}
.v7 .v7-more summary::-webkit-details-marker{display:none}
.v7 .v7-more summary::after{content:'';width:6px;height:6px;border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;transform:rotate(45deg) translate(-2px,-2px)}
.v7 .v7-more[open] summary::after{transform:rotate(-135deg) translate(-1px,-1px)}
.v7 .v7-row{display:flex;gap:8px;padding:8px 4px;border-top:1px solid var(--border);border-radius:6px}
.v7 .v7-row:hover,.v7 .v7-row:active{background:var(--surface2)}
.v7 .v7-row .v7-disc{margin-top:2px}
.v7 .v7-rbody{flex:1 1 auto;display:flex;flex-direction:column;gap:3px}
.v7 .v7-l1{display:flex;align-items:center;gap:6px}
.v7 .v7-l1 .v7-name{flex:1 1 auto;font-size:13px;font-weight:600}
.v7 .v7-l1 .v7-chev{font-size:16px;margin-left:2px}
.v7 .v7-l2{display:flex;flex-wrap:wrap;align-items:center;gap:3px 7px;font-size:11px;color:var(--muted)}
.v7 .v7-l2 b{font-size:12px;font-weight:700}
.v7 .v7-l3{display:flex;flex-wrap:wrap;align-items:center;gap:3px 6px}
.v7 .v7-l3 b{font-size:13px;font-weight:700}
.v7 .v7-l4{font-size:11px;color:var(--muted)}
.v7 .v7-none{margin:6px 0 0;padding:8px 4px 2px;border-top:1px solid var(--border);font-size:12px;color:var(--muted)}
.v7 .v7-sm .v7-abbr{font-size:16px}
.v7 .v7-sm .v7-bar{height:26px;font-size:13px}
.v7 .v7-sm .v7-feat{padding:8px}
.v7 .v7-sm .v7-disc-lg{width:32px;height:32px;font-size:12px}
.v7 .v7-sm .v7-name{font-size:13px}
.v7 .v7-sm .v7-stats{margin:8px 0 6px;padding:6px 0}
.v7 .v7-sm .v7-stats b{font-size:12px}
.v7 .v7-sm .v7-pick b{font-size:13px}
.v7 .v7-humble{margin:4px 0 0;font-size:13px;color:var(--text)}
.v7 .v7-unq{margin:6px 0 0;font-size:12px;color:var(--muted)}
.v7 .v7-note{margin:14px 0 0;padding-top:10px;border-top:1px solid var(--border);font-size:11px;line-height:1.45;color:var(--muted)}
@media (min-width:560px){.v7 .v7-split{gap:0 10px}.v7 .v7-side{padding:10px}.v7 .v7-feat{padding:14px}.v7 .v7-sm .v7-feat{padding:10px}}
